package main
import("encoding/json";"fmt";"os";"strconv";"github.com/qjfoidnh/BaiduPCS-Go/internal/pcsconfig";"github.com/qjfoidnh/BaiduPCS-Go/baidupcs")
func fail(e interface{}){json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"error":fmt.Sprint(e)});os.Exit(1)}
func item(f *baidupcs.FileDirectory)map[string]interface{}{return map[string]interface{}{"id":strconv.FormatInt(f.FsID,10),"name":f.Filename,"path":f.Path,"isDir":f.Isdir,"size":f.Size,"modified":f.Mtime*1000,"hash":f.MD5,"hashType":"baidu-md5"}}
func main(){if len(os.Args)<2{fail("operation required")};if e:=pcsconfig.Config.Init();e!=nil{fail(e)};pcsconfig.Config.EnableHTTPS=true;if os.Args[1]=="login"{var p struct{BDUSS string `json:"bduss"`;PTOKEN string `json:"ptoken"`;STOKEN string `json:"stoken"`;Cookies string `json:"cookies"`};if e:=json.NewDecoder(os.Stdin).Decode(&p);e!=nil{fail("登录输入无效")};if p.BDUSS==""&&p.Cookies==""{fail("请输入百度 Cookie 或 BDUSS")};if _,e:=pcsconfig.Config.SetupUserByBDUSS(p.BDUSS,p.PTOKEN,p.STOKEN,p.Cookies);e!=nil{fail("百度授权校验失败")};if e:=pcsconfig.Config.Save();e!=nil{fail(e)};json.NewEncoder(os.Stdout).Encode(map[string]bool{"ok":true});return};if len(os.Args)<3{fail("path required")};if pcsconfig.Config.ActiveUser()==nil{fail("请先连接百度网盘")};p:=pcsconfig.Config.ActiveUserBaiduPCS();switch os.Args[1]{case "list":l,e:=p.FilesDirectoriesList(os.Args[2],&baidupcs.OrderOptions{By:baidupcs.OrderByName,Order:baidupcs.OrderAsc});if e!=nil{fail(e)};out:=[]map[string]interface{}{};for _,f:=range l{out=append(out,item(f))};json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"items":out});case "stat":f,e:=p.FilesDirectoriesMeta(os.Args[2]);if e!=nil{fail(e)};json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"item":item(f)});default:fail("unsupported operation")}}
